inline Art decode(unsigned w,const unsigned short*r,size_t n){Art a{w,{}};a.rgba.assign(size_t(w)*128*4,255);size_t at=0;for(size_t i=0;i<n;i+=2){ck(i+1<n&&r[i]&&r[i+1]<256&&at+r[i]<=size_t(w)*128,"independent Graphics RLE bounded");for(unsigned j=0;j<r[i];++j)a.rgba[4*(at++)+3]=static_cast<unsigned char>(r[i+1]);}ck(at==size_t(w)*128,"independent Graphics RLE complete");return a;}
