 NFS_GD_TEST_ART(1,360);NFS_GD_TEST_ART(2,420);NFS_GD_TEST_ART(3,480);NFS_GD_TEST_ART(4,304);NFS_GD_TEST_ART(5,132);NFS_GD_TEST_ART(6,140);NFS_GD_TEST_ART(7,204);NFS_GD_TEST_ART(8,272);
