inline double alpha(const Art&a,double x,double y,const NfsGraphicsDialogWordPlacement&p){if(x<p.left||x>=p.right||y<p.top||y>=p.bottom)return 0;double X=std::max(0.,std::min(double(a.w-1),(x-p.left)*4-.5)),Y=std::max(0.,std::min(127.,(y-p.top)*4-.5));unsigned i=unsigned(X),j=unsigned(Y),k=std::min(i+1,a.w-1),l=std::min(j+1,127u);double fx=X-i,fy=Y-j;auto at=[&](unsigned x,unsigned y){return double(a.rgba[(size_t(y)*a.w+x)*4+3]);};return ((at(i,j)*(1-fx)+at(k,j)*fx)*(1-fy)+(at(i,l)*(1-fx)+at(k,l)*fx)*fy)/255.;}
inline void blend(double rgb[3],const double color[3],double a){for(unsigned k=0;k<3;++k)rgb[k]=std::round(color[k]*a+rgb[k]*(1-a));}
